#!/usr/bin/env bash
# The estimate of stage A of the RefC flat layout design
# (docs/source/backends/refc-flat-layout.rst), on the particles workload of
# the ownership experiment's phase 0: hand edits of the generated C.
#
#   A    as-is RefC
#   AD   A with the Double locals of move and bounce unboxed (phase 0's patch)
#   SA   stage A: AD with the fields of MkParticle raw in its cell
#   SA0  SA with the linear array owned and Res returned as a C struct
#   FD   phase 0's flat layout (patch)
#
# The patches and edits are against the C generated by the compiler of
# 9802e1859d; a compiler that generates other C for this program needs them
# redone.  Usage: run.sh [-n RUNS] [-q]   (-q: the fast input only)
set -eu

here="$(cd "$(dirname "$0")" && pwd)"
RUNS=3
QUICK=false
while getopts ":n:q" opt; do
  case "$opt" in
    n) RUNS="$OPTARG" ;;
    q) QUICK=true ;;
    *) echo "usage: run.sh [-n RUNS] [-q]" >&2; exit 1 ;;
  esac
done

IDRIS2="${IDRIS2:-idris2}"
LIBDIR="$("$IDRIS2" --libdir)"
WORK="$here/build"
export TMPDIR="$WORK/tmp"
unset IDRIS2_CFLAGS CFLAGS IDRIS2_CC CC
rm -rf "${WORK:?}"
mkdir -p "$WORK" "$TMPDIR"

compile_c() { # src.c exe
  cc -Werror -c "$1" -o "${2}.o" -I"$LIBDIR/support/refc" -I"$LIBDIR/support/c" -O2
  cc -Werror "${2}.o" -o "$2" "$LIBDIR/lib/libidris2_support.a" -lidris2_refc \
    -L"$LIBDIR/support/refc" -L"$LIBDIR/lib" -lgmp -lm -pthread -O2
}

cp "$here/particles.idr" "$WORK/"
(cd "$WORK" && "$IDRIS2" --cg refc -p contrib -o particles particles.idr >/dev/null)
gen="$WORK/build/exec/particles.c"
mkdir -p "$WORK/A"
cp "$WORK/build/exec/particles" "$WORK/A/particles"
for v in AD FD; do
  mkdir -p "$WORK/$v"
  cp "$gen" "$WORK/$v/particles.c"
  patch -s "$WORK/$v/particles.c" "$here/patches/particles_$v.patch"
  compile_c "$WORK/$v/particles.c" "$WORK/$v/particles"
done
for v in SA SA0; do
  mkdir -p "$WORK/$v"
  python3 -I "$here/splice.py" "$gen" "$here/edits/particles_$v.c" "$WORK/$v/particles.c"
  compile_c "$WORK/$v/particles.c" "$WORK/$v/particles"
done

inputs="particles_fast.in"
$QUICK || inputs="$inputs particles.in"
for i in $inputs; do
  ref="$("$WORK/A/particles" < "$here/$i")"
  for v in AD SA SA0 FD; do
    out="$("$WORK/$v/particles" < "$here/$i")"
    [ "$out" = "$ref" ] || { echo "MISMATCH $v $i: '$out' (A: '$ref')" >&2; exit 1; }
  done
  for v in A AD SA SA0 FD; do
    ns=""
    for r in $(seq 1 "$RUNS"); do
      perf stat -x, -e instructions:u -o "$WORK/perf.txt" "$WORK/$v/particles" < "$here/$i" > /dev/null
      ns="$ns $(awk -F, '$3 ~ /^instructions/ {print $1}' "$WORK/perf.txt")"
    done
    echo "$i $v median instructions: $(echo $ns | tr ' ' '\n' | sort -n | sed -n "$(( (RUNS + 1) / 2 ))p")"
  done
done
